   449→async function importDocumentsPackagesFields(req, res) {
   450→
   451→    if (!req.file) {
   452→        return res.status(400).send({
   453→          status: false,
   454→          message: "No se ha subido ningún archivo",
   455→          errors: [
   456→            {
   457→              field_name: "file",
   458→            },
   459→          ],
   460→        });
   461→    }
   462→
   463→    const countryId = req.body.countryId;
   464→
   465→    const file = req.file;
   466→    const workbook = new ExcelJS.Workbook();
   467→
   468→    await workbook.xlsx.readFile(file.path);
   469→
   470→    const worksheet = workbook.getWorksheet(1);
   471→    if (!worksheet) {
   472→        return res.status(400).send({
   473→            status: false,
   474→            message: "El archivo no contiene hojas válidas.",
   475→            errors: [{ field_name: "file" }],
   476→        });
   477→    }
   478→        
   479→    let hasData = false;
   480→    worksheet.eachRow((row, rowNumber) => {
   481→        if (rowNumber > 1) {
   482→            let rowHasRealData = false;
   483→    
   484→            row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
   485→                if (cell.value !== null && cell.value !== '' && typeof cell.value !== 'object') {
   486→                    rowHasRealData = true;
   487→                }
   488→            });
   489→    
   490→            if (rowHasRealData) {
   491→                hasData = true;
   492→            } else {
   493→                console.log(`Fila ${rowNumber} solo contiene validaciones o está vacía.`);
   494→            }
   495→        }
   496→    });
   497→    
   498→    if (!hasData) {
   499→        return res.status(400).send({
   500→            status: false,
   501→            message: "El archivo está vacío o solo contiene validaciones de datos sin valores.",
   502→            errors: [{ field_name: "file" }],
   503→        });
   504→    }
   505→
   506→    try {
   507→        const documentTypes = await db.identification_types.findMany({
   508→            where: {
   509→                country_id: parseInt(countryId),
   510→            },
   511→            select: {
   512→                id: true,
   513→                name: true,
   514→                field_type: true,
   515→            }
   516→        });
   517→
   518→        const documentTypeMap = {};
   519→        const documentTypeIdMap = {};
   520→
   521→        documentTypes.forEach(type => {
   522→            documentTypeMap[type.name] = type.field_type;
   523→            documentTypeIdMap[type.name] = type.id;
   524→        });
   525→
   526→       
   527→        let headers = {};
   528→        let fields = [];
   529→        let signers = [];
   530→
   531→        worksheet.getRow(1).eachCell((cell, colNumber) => {
   532→            headers[cell.text] = colNumber; 
   533→            if (cell.text.startsWith('Firmante')) {
   534→                signers.push(cell.text);
   535→            } else if (!['Fecha y hora límite para realizar la firma', 'Número de contrato'].includes(cell.text)) {
   536→                fields.push(cell.text); 
   537→            }
   538→        });
   539→
   540→        let dataArr = [];
   541→        let errors = []; 
   542→
   543→        const isValidEmail = (email) => {
   544→            return /\S+@\S+\.\S+/.test(email);
   545→        };
   546→
   547→        const isValidPhoneNumber = (phone) => {
   548→            return /^\d{10,14}$/.test(phone);
   549→        };
   550→
   551→
   552→        worksheet.eachRow({ includeEmpty: true }, function(row, rowNumber) {
   553→            if (rowNumber !== 1) { 
   554→
   555→                let isRowEmpty = true;
   556→                row.eachCell({ includeEmpty: true }, function(cell, colNumber) {
   557→                    if (cell.value !== null && cell.value !== '') {
   558→                        isRowEmpty = false;
   559→                    }
   560→                });
   561→
   562→                if (row.actualCellCount === 0 || row.values.every(cell => cell === null || cell === '')) {
   563→                    return;
   564→                }
   565→                
   566→                let errorsRow = [];
   567→
   568→                const expiresInDaysCell = row.getCell(headers['Fecha límite para realizar la firma']);
   569→                const expiresInDays = expiresInDaysCell ? expiresInDaysCell.value : null;
   570→
   571→                let expiresDate;
   572→                if (!expiresInDays) {
   573→                    errorsRow.push(`La fecha en la fila ${rowNumber} no tiene valor.`);
   574→                } else {
   575→                    if (expiresInDays instanceof Date) {
   576→                        expiresDate = expiresInDays;
   577→                    } else if (typeof expiresInDays === 'string' || typeof expiresInDays === 'number') {
   578→                        expiresDate = new Date(expiresInDays);
   579→                        if (isNaN(expiresDate)) {
   580→                            errorsRow.push(`La fecha en la fila ${rowNumber} no es válida.`);
   581→                        }
   582→                    } else {
