   694→function cleanCellValue(value) {
   695→    if (value === null || value === undefined) return '';
   696→
   697→    if (value instanceof Date) {
   698→        return value; 
   699→    }
   700→
   701→    if (typeof value === 'number') {
   702→        return value;
   703→    }
   704→
   705→    if (typeof value === 'boolean') {
   706→        return value;
   707→    }
   708→
   709→    if (typeof value === 'string') {
   710→        return value.trim();
   711→    }
   712→
   713→    if (typeof value === 'object') {
   714→
   715→        if (Array.isArray(value.richText)) {
   716→            return value.richText.map(v => v.text || '').join('').trim();
   717→        }
   718→
   719→        if (value.text) {
   720→            return String(value.text).trim();
   721→        }
   722→        if (value.formula !== undefined) {
   723→            if (value.result instanceof Date) return value.result;
   724→            return value.result || '';
   725→        }
   726→
   727→        return '';
   728→    }
   729→
   730→    return String(value).trim();
   731→}
