        const signers_fields = req.body.signers_fields;

        const documentTypes = await db.identification_types.findMany({
            where: {
                country_id: parseInt(countryId),
            },
            select: {
                id: true,
                name: true,
                field_type: true,
            }
        });

        const signers_names = signers_fields.map(field => {
            return field.name.replace(/\[\$|\]/g, '');  
        });

        const workbook = new ExcelJS.Workbook();
        const worksheet = workbook.addWorksheet('Cargue Masivo');       

        const columns = [
            { header: 'Fecha límite para realizar la firma', key: 'expires_in_days', width: 30 },
            { header: 'Número de contrato', key: 'contract_number', width: 20 },
        ];

        const doctypeColumnKeys = [];
        const documentColumnKeys = [];
        const phoneColumnKeys = [];
        const emailColumnKeys = [];

        signers_names.forEach((field, index) => {

            const match = field.match(/FIRMA(\d+)/);
            const signerNumber = match ? match[1] : '';

            columns.push({ header: `Firmante${signerNumber}_Nombre`, key: `signer${signerNumber}_name`, width: 15 });
            columns.push({ header: `Firmante${signerNumber}_Apellido`, key: `signer${signerNumber}_surname`, width: 15 });
            const emailKey = `signer${signerNumber}_email`;
            columns.push({ header: `Firmante${signerNumber}_Correo`, key: emailKey, width: 30 });
            emailColumnKeys.push(emailKey);

            const phoneKey = `signer${signerNumber}_phone`;
            columns.push({ header: `Firmante${signerNumber}_Celular`, key: phoneKey, width: 20 });
            phoneColumnKeys.push(phoneKey);

            const doctypeKey = `signer${signerNumber}_doctype`;
            columns.push({ header: `Firmante${signerNumber}_Tipo_documento`, key: doctypeKey, width: 30 });
            doctypeColumnKeys.push(doctypeKey);

            const documentKey = `signer${signerNumber}_document`;
            columns.push({ header: `Firmante${signerNumber}_Documento`, key: documentKey, width: 20 });
            documentColumnKeys.push(documentKey);
        });

        worksheet.columns = columns;
        const listWorksheet = workbook.addWorksheet('Lists', { state: 'hidden' });
        documentTypes.forEach((type, index) => {
            listWorksheet.getCell(`A${index + 1}`).value = type.name;
            listWorksheet.getCell(`B${index + 1}`).value = type.field_type;
        });

        doctypeColumnKeys.forEach(doctypeKey => {
            const column = worksheet.getColumn(doctypeKey);
            for (let rowIndex = 2; rowIndex <= 501; rowIndex++) {
                const cell = worksheet.getCell(rowIndex, column.number);
                cell.dataValidation = {
                    type: 'list',
                    allowBlank: true,
                    formulae: [`Lists!$A$1:$A$${documentTypes.length}`]
                };
            }
        });

        documentColumnKeys.forEach((documentKey, index) => {
            const doctypeKey = doctypeColumnKeys[index]; 
            const documentColumn = worksheet.getColumn(documentKey);
            const doctypeColumn = worksheet.getColumn(doctypeKey);

            for (let rowIndex = 2; rowIndex <= 501; rowIndex++) {
                const documentCell = worksheet.getCell(rowIndex, documentColumn.number);
                const doctypeCellAddress = worksheet.getCell(rowIndex, doctypeColumn.number).address;

                documentCell.dataValidation = {
                    type: 'custom',
                    allowBlank: true,
                    showErrorMessage: true,
                    errorStyle: 'error',
                    errorTitle: 'Valor inválido',
                    error: 'El documento debe ser numérico o alfanumérico y tener al menos 6 caracteres, según el tipo de documento seleccionado.',
                    formulae: [
                        `=IF(
                            INDIRECT("Lists!$B$"&MATCH(${doctypeCellAddress},Lists!$A$1:$A$${documentTypes.length},0))="numeric",
                            AND(ISNUMBER(${documentCell.address}),LEN(${documentCell.address})>=6),
                            LEN(${documentCell.address})>=6
                        )`
                    ]
                };
            }
        });

        phoneColumnKeys.forEach(phoneKey => {
            const column = worksheet.getColumn(phoneKey);
            for (let rowIndex = 2; rowIndex <= 501; rowIndex++) {
                const cell = worksheet.getCell(rowIndex, column.number);
                cell.dataValidation = {
                    type: 'custom',
                    allowBlank: true,
                    showErrorMessage: true,
                    errorStyle: 'error',
                    errorTitle: 'Celular inválido',
                    error: 'El celular debe ser numérico y tener entre 10 y 14 dígitos.',
                    formulae: [`=AND(ISNUMBER(${cell.address}),LEN(${cell.address})>=10,LEN(${cell.address})<=14)`]
                };
            }
        });

        emailColumnKeys.forEach(emailKey => {
            const column = worksheet.getColumn(emailKey);
            for (let rowIndex = 2; rowIndex <= 501; rowIndex++) {
                const cell = worksheet.getCell(rowIndex, column.number);
                cell.dataValidation = {
                    type: 'custom',
                    allowBlank: true,
                    showErrorMessage: true,
                    errorStyle: 'error',
                    errorTitle: 'Correo inválido',
                    error: 'Por favor, ingrese un correo electrónico válido.',
                    formulae: [`=AND(
                        ISERROR(FIND(" ",${cell.address})),
                        FIND("@",${cell.address})>1,
                        FIND(".",${cell.address},FIND("@",${cell.address})+1)>FIND("@",${cell.address})+1
                    )`]
                };
            }
        });

        const dateColumn = worksheet.getColumn('expires_in_days');

        dateColumn.eachCell({ includeEmpty: true }, (cell, rowNumber) => {
            if (rowNumber > 1) {
                cell.dataValidation = {
                    type: 'date',
                    allowBlank: true,
                    showErrorMessage: true,
                    operator: 'greaterThan', 
                    errorStyle: 'error',
                    errorTitle: 'Fecha inválida',
                    error: 'Por favor, ingrese una fecha igual o mayor a la fecha actual en el formato DD/MM/AAAA.',
                    formula1: '=TODAY()',
                };
                cell.numFmt = 'dd/mm/yyyy';  

            }
        });

        const tempFilePath = `./template_${Date.now()}`;

        workbook.xlsx.writeFile(tempFilePath).then(() => {
            fs.readFile(tempFilePath, (err, data) => {

              if (err) {
                console.error(err);
                res.status(500).send({
                  status: false,
                  message: "Error al generar archivo de Excel",
                });
              } else {
                res.status(200)
                  .header({
                    "Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    "Content-Disposition": `attachment; filename="cargue_masivo.xlsx"`,
                    "Content-Length": data.length,
                  })
                  .send(data);
              }

              fs.unlink(tempFilePath, () => {});

            });
        }); 


    } catch (err) {
        console.log(err);
        res.status(404).send({
            status: false,
            message: err,
        });
    }
}
