#### Function 3: importDocumentsPackagesFields (lines 449-692)
Imports filled Excel and validates data. Returns structured data for processing.

```javascript
async function importDocumentsPackagesFields(req, res) {

    if (!req.file) {
        return res.status(400).send({
          status: false,
          message: "No se ha subido ningún archivo",
          errors: [
            {
              field_name: "file",
            },
          ],
        });
    }

    const countryId = req.body.countryId;

    const file = req.file;
    const workbook = new ExcelJS.Workbook();

    await workbook.xlsx.readFile(file.path);

    const worksheet = workbook.getWorksheet(1);
    if (!worksheet) {
        return res.status(400).send({
            status: false,
            message: "El archivo no contiene hojas válidas.",
            errors: [{ field_name: "file" }],
        });
    }

    let hasData = false;
    worksheet.eachRow((row, rowNumber) => {
        if (rowNumber > 1) {
            let rowHasRealData = false;

            row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
                if (cell.value !== null && cell.value !== '' && typeof cell.value !== 'object') {
                    rowHasRealData = true;
                }
            });

            if (rowHasRealData) {
                hasData = true;
            } else {
                console.log(`Fila ${rowNumber} solo contiene validaciones o está vacía.`);
            }
        }
    });

    if (!hasData) {
        return res.status(400).send({
            status: false,
            message: "El archivo está vacío o solo contiene validaciones de datos sin valores.",
            errors: [{ field_name: "file" }],
        });
    }

    try {
        const documentTypes = await db.identification_types.findMany({
            where: {
                country_id: parseInt(countryId),
            },
            select: {
                id: true,
                name: true,
                field_type: true,
            }
        });

        const documentTypeMap = {};
        const documentTypeIdMap = {};

        documentTypes.forEach(type => {
            documentTypeMap[type.name] = type.field_type;
            documentTypeIdMap[type.name] = type.id;
        });


        let headers = {};
        let fields = [];
        let signers = [];

        worksheet.getRow(1).eachCell((cell, colNumber) => {
            headers[cell.text] = colNumber; 
            if (cell.text.startsWith('Firmante')) {
                signers.push(cell.text);
            } else if (!['Fecha y hora límite para realizar la firma', 'Número de contrato'].includes(cell.text)) {
                fields.push(cell.text); 
            }
        });

        let dataArr = [];
        let errors = []; 

        const isValidEmail = (email) => {
            return /\S+@\S+\.\S+/.test(email);
        };

        const isValidPhoneNumber = (phone) => {
            return /^\d{10,14}$/.test(phone);
        };


        worksheet.eachRow({ includeEmpty: true }, function(row, rowNumber) {
            if (rowNumber !== 1) { 

                let isRowEmpty = true;
                row.eachCell({ includeEmpty: true }, function(cell, colNumber) {
                    if (cell.value !== null && cell.value !== '') {
                        isRowEmpty = false;
                    }
                });

                if (row.actualCellCount === 0 || row.values.every(cell => cell === null || cell === '')) {
                    return;
                }

                let errorsRow = [];

                const expiresInDaysCell = row.getCell(headers['Fecha límite para realizar la firma']);
                const expiresInDays = expiresInDaysCell ? expiresInDaysCell.value : null;

                let expiresDate;
                if (!expiresInDays) {
                    errorsRow.push(`La fecha en la fila ${rowNumber} no tiene valor.`);
                } else {
                    if (expiresInDays instanceof Date) {
                        expiresDate = expiresInDays;
                    } else if (typeof expiresInDays === 'string' || typeof expiresInDays === 'number') {
                        expiresDate = new Date(expiresInDays);
                        if (isNaN(expiresDate)) {
                            errorsRow.push(`La fecha en la fila ${rowNumber} no es válida.`);
                        }
                    } else {
                        errorsRow.push(`La fecha en la fila ${rowNumber} no es válida.`);
                    }

                    if (expiresDate) {
                        const today = new Date();
                        today.setHours(0, 0, 0, 0);

                        expiresDate.setHours(0, 0, 0, 0);

                        if (expiresDate < today) {
                            errorsRow.push(`La fecha en la fila ${rowNumber} debe ser igual o mayor a la fecha actual.`);
                        }
                    }
                }

                const contractNumberCell = row.getCell(headers['Número de contrato']);
                const contractNumber = contractNumberCell ? contractNumberCell.value : null;

                if (contractNumber == null || contractNumber === '') {
                    errorsRow.push(`El campo "Número de contrato" en la fila ${rowNumber} no tiene valor.`);
                }

                let dynamicFields = {};
                let signerFields = {};
                let tipoDocumentoPerSigner = {};

                Object.keys(headers).forEach((header) => {
                    const colIndex = headers[header];
                    let cell = row.getCell(colIndex);
                   let rawValue = cell ? cell.value : null;
                    let value = cleanCellValue(rawValue);

                    if (typeof value === 'object' && value && value.text) {
                        value = value.text;
                    }

                    if (value === null || value === '') {
                        errorsRow.push(`La celda "${header}" en la fila ${rowNumber} no tiene valor.`);
                    }

                    if (header.includes('Correo')) {
                        if (!isValidEmail(value)) {
                            errorsRow.push(`El valor en la celda "${header}" en la fila ${rowNumber} no es un correo válido.`);
                        } else {
                            signerFields[header] = value;
                        }
                    } else if (header.includes('Celular')) {
                        if (!isValidPhoneNumber(value)) {
                            errorsRow.push(`El valor en la celda "${header}" en la fila ${rowNumber} no es válido. Debe ser numérico y tener entre 10 y 14 dígitos.`);
                        } else {
                            signerFields[header] = value;
                        }
                    } else if (header.includes('Tipo_documento')) {
                        const documentTypeName = value;
                        const documentTypeId = documentTypeIdMap[documentTypeName];
                        if (!documentTypeId) {
                            errorsRow.push(`El Tipo_documento "${documentTypeName}" en la fila ${rowNumber} no es válido.`);
                        } else {
                            signerFields[header] = documentTypeId;
                            const signerKey = header.split('_')[0];
                            tipoDocumentoPerSigner[signerKey] = documentTypeId;
                        }
                    } else if (header.includes('Documento')) {
                        signerFields[header] = value;

                    } else if (signers.includes(header)) {
                        if (value === null || value === '') {
                            errorsRow.push(`El campo "${header}" en la fila ${rowNumber} no tiene valor.`);
                        } else {
                            signerFields[header] = value;
                        }
                    } else {
                        dynamicFields[header] = value;
                    }
                });

                console.log(errorsRow);
                if (errorsRow.length === 0) {


                    dataArr.push({ expiresInDays: expiresDate, contractNumber, dynamicFields, signerFields });
                } else {
                    errors = errors.concat(errorsRow);
                }
            }
        });

        fs.unlink(file.path, (err) => {
            if (err) throw err;
            console.log(`Archivo eliminado: ${file.path}`);
        });

        res.status(200).send({
            status: true,
            data: {
                data: dataArr,
                documentHeaderId: req.body.documentHeaderId,
                errors: errors,
            },
            message: "Datos recibidos correctamente",
        });

    } catch (err) {
        console.log(err);
        res.status(404).send({
            status: false,
            message: err,
        });
    }
}
